package android.os;import java.util.*;public class Messenger implements Parcelable{public static class Endpoint implements IBinder{public final Handler h;public final List<DeathRecipient> deaths=new ArrayList<>();public boolean dead;Endpoint(Handler h){this.h=h;}public void linkToDeath(DeathRecipient d,int f)throws RemoteException{if(dead)throw new RemoteException();deaths.add(d);}public boolean unlinkToDeath(DeathRecipient d,int f){return deaths.remove(d);}public void die(){dead=true;for(DeathRecipient d:new ArrayList<>(deaths))d.binderDied();}}private final Endpoint b;public Messenger(Handler h){b=new Endpoint(h);}public Messenger(IBinder b){this.b=(Endpoint)b;}public IBinder getBinder(){return b;}public void send(Message m)throws RemoteException{if(b.dead)throw new RemoteException();m.sendingUid=Process.myUid();b.h.dispatch(m);}}
